import math

# Let me try to create test data to better understand the hash.
# I need to look at single-character names to understand the mapping.

# Let me generate test input files with single-character frame names
# to see their colors.
# a, b, c, d, e, f, g, h, i...

# Actually, let me think about what crate flamelens uses.
# Looking at flamelens - it's a TUI flamegraph viewer.
# It likely uses the `inferno` crate for parsing flamegraph data.
# 
# The inferno hot color algorithm is from:
# https://github.com/brendangregg/FlameGraph/blob/master/flamegraph.pl
# which uses: 
#   r1 = 1 + int(rand(0)*205); g1 = 0 + int(rand(0)*230); b1 = 0 + int(rand(0)*55);
#   where rand(seed) uses the name as seed
# 
# The seed-based rand is: sum of character values (byte values)
# scaled to [0, 1) using the total as a "modulus"
# 
# The original flamegraph.pl does:
# sub color_map {
#     my ($type, $name) = @_;
#     ...
#     my $v1 = 1; my $v2 = 1; my $v3 = 1;
#     if ($nametype eq "func") {
#         my $namesum = 0;
#         foreach my $c (split //, $name) {
#             $namesum += ord($c);
#         }
#         $v1 = $namesum / (length($name) * 256);
#         $v2 = $v1; $v3 = $v1;  # same for hot
#     }
#     ...
#     my $r = 205 + int(50 * $v1);
#     my $g = int(230 * $v2);
#     my $b = int(55 * $v3);
# }
# 
# This uses average char value! Let me try this:

def flamegraph_pl_hash(s):
    if not s:
        return 0.0
    total = sum(ord(c) for c in s)
    return total / (len(s) * 256.0)

def color_from_v(v):
    r = 205 + int(v * 50)
    g = int(v * 230)
    b = int(v * 55)
    return (r, g, b)

observed = {
    "all": (205, 3, 0),
    "main": (244, 180, 43),
    "foo": (214, 44, 10),
    "qux": (251, 212, 50),
    "bar": (252, 218, 52),
    "baz": (254, 229, 54),
    "deep": (225, 94, 22),
    "aaaa": (227, 102, 24),
    "ffff": (208, 17, 4),
    "bbbb": (228, 109, 26),
    "dddd": (210, 26, 6),
    "gggg": (222, 79, 19),
    "cccc": (214, 43, 10),
    "eeee": (245, 185, 44),
    "hhhh": (216, 51, 12),
}

print("Testing flamegraph.pl hash (avg char value):")
all_match = True
for name, expected_rgb in observed.items():
    v = flamegraph_pl_hash(name)
    actual_rgb = color_from_v(v)
    match = "✓" if actual_rgb == expected_rgb else "✗"
    if actual_rgb != expected_rgb:
        all_match = False
    print(f"  {match} {name}: v={v:.6f}, actual_rgb={actual_rgb}, expected_rgb={expected_rgb}")

print(f"\nAll match: {all_match}")

