#     let mut v: f64 = 0.0;
#     for (i, c) in name.chars().enumerate() {
#         let ord = c as u32;
#         v += (((ord >> 5) ^ ord) * (i + 1)) as f64;  // mixing bits
#     }
#     v / ((namesize + 1.0) * 64.0)
# }
# 
# Hmm, let me try this:

import math

def inferno_hash_v3(s):
    namesize = len(s)
    v = 0.0
    for i, c in enumerate(s):
        ord_val = ord(c)
        v += ((ord_val >> 5) ^ ord_val) * (i + 1)
