fn frame_hash(path: &str) -> u64 {
    let mut h = DefaultHasher::new();
    path.hash(&mut h);
    h.finish()
}

fn frame_color(path: &str) -> (u8, u8, u8) {
    let h = frame_hash(path);
    let v = (h as f64) / (u64::MAX as f64 + 1.0);
